def restore_route23_text(path, text):
    if str(path) != "src/data/wild_encounters.json":
        return text
    for label, original in ORIGINAL_ROUTE23.items():
        marker = '"base_label": "' + label + '"'
        start = text.index(marker)
        i = text.index('"mons": [', start)
        assert text[i:i+len(BALANCED_ROUTE23)] == BALANCED_ROUTE23, label
        text = text[:i] + original + text[i+len(BALANCED_ROUTE23):]
    return text

def prior_route23_source(path):
    return restore_route23_text(path, prior_route22_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_route23_text(path, text):
    return restore_route23_text(path, restore_prior_route22_text(path, text))
